//! IEEE OUI lookup over the embedded table (`data/oui.tsv`, generated by
//! `cargo xtask oui`).

use std::collections::HashMap;
use std::sync::OnceLock;

const TABLE: &str = include_str!("../data/oui.tsv");

/// Parse `aa:bb:cc:dd:ee:ff` (any case) into bytes.
pub fn parse_mac(mac: &str) -> Option<[u8; 6]> {
    let mut out = [0u8; 6];
    let mut parts = mac.split(':');
    for slot in &mut out {
        let p = parts.next()?;
        if p.len() != 2 || !p.bytes().all(|b| b.is_ascii_hexdigit()) {
            return None;
        }
        *slot = u8::from_str_radix(p, 16).ok()?;
    }
    parts.next().is_none().then_some(out)
}

/// Locally administered bit set (randomised or virtual address).
pub fn is_private(mac: &str) -> bool {
    parse_mac(mac).is_some_and(|m| m[0] & 0x02 != 0)
}

fn table() -> &'static HashMap<&'static str, &'static str> {
    static MAP: OnceLock<HashMap<&'static str, &'static str>> = OnceLock::new();
    MAP.get_or_init(|| {
        TABLE
            .lines()
            .filter(|l| !l.starts_with('#'))
            .filter_map(|l| l.split_once('\t'))
            .collect()
    })
}

/// Short maker name for a MAC; `None` for private MACs and unknown prefixes.
///
/// The longest registered prefix wins: 9 hex digits (MA-S), then 7 (MA-M),
/// then 6 (MA-L).
pub fn lookup(mac: &str) -> Option<&'static str> {
    let m = parse_mac(mac)?;
    if m[0] & 0x02 != 0 {
        return None;
    }
    let hex: String = m.iter().map(|b| format!("{b:02X}")).collect();
    let t = table();
    [9, 7, 6].iter().find_map(|n| t.get(&hex[..*n]).copied())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn raspberry_pi_prefixes() {
        assert_eq!(lookup("b8:27:eb:7d:4e:25"), Some("Raspberry Pi"));
        assert_eq!(lookup("DC:A6:32:02:8E:35"), Some("Raspberry Pi"));
    }

    #[test]
    fn known_prefix_has_a_name() {
        assert!(lookup("7c:78:b2:14:b2:de").is_some());
    }

    #[test]
    fn private_mac_is_none() {
        assert_eq!(lookup("02:cf:67:c6:7b:71"), None);
        assert!(is_private("02:cf:67:c6:7b:71"));
        assert!(!is_private("b8:27:eb:7d:4e:25"));
    }

    #[test]
    fn garbage_is_none() {
        assert_eq!(lookup("zz"), None);
        assert_eq!(lookup("aa:bb:cc:dd:ee"), None);
        assert!(!is_private("zz"));
        assert_eq!(
            parse_mac("AA:bb:0c:dd:ee:ff"),
            Some([0xaa, 0xbb, 0x0c, 0xdd, 0xee, 0xff])
        );
    }

    /// MA-S blocks resolve to their own holder; their 6-digit parents
    /// ("IEEE Registration Authority") and hidden ("Private") registrations
    /// are not in the table, so they never name a host.
    #[test]
    fn nine_digit_prefix_is_found_and_placeholders_are_absent() {
        let rows: Vec<(&str, &str)> = TABLE
            .lines()
            .filter(|l| !l.starts_with('#'))
            .filter_map(|l| l.split_once('\t'))
            .collect();
        assert!(
            rows.iter()
                .all(|(_, n)| *n != "Private" && *n != "IEEE Registration Authority")
        );
        let (long, name) = rows
            .iter()
            .find(|(p, _)| p.len() == 9)
            .expect("a MA-S block");
        let mac = format!(
            "{}:{}:{}:{}:{}0:00",
            &long[0..2],
            &long[2..4],
            &long[4..6],
            &long[6..8],
            &long[8..9]
        );
        assert_eq!(lookup(&mac), Some(*name));
        // Raspberry Pi's MA-L block is unaffected
        assert_eq!(lookup("b8:27:eb:00:00:01"), Some("Raspberry Pi"));
    }
}
